const emptyCoupon = { code: '', discountType: 'percentage', discountValue: '', minimumOrderAmount: 0, maximumDiscount: '', startDate: '', expiryDate: '', usageLimit: '', enabled: true }
function AdminCoupons({ adminKey }) {
  const [coupons, setCoupons] = useState([]); const [search, setSearch] = useState(''); const [status, setStatus] = useState('all'); const [page, setPage] = useState(1); const [pages, setPages] = useState(1); const [total, setTotal] = useState(0); const [form, setForm] = useState(null); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const [toast, setToast] = useState('')
  const load = async (nextPage = page) => { setLoading(true); setError(''); try { const query = new URLSearchParams({ page: String(nextPage), search, status }); const response = await fetch(`http://localhost:4000/api/admin/coupons?${query}`, { headers: { 'x-admin-key': adminKey } }); const body = await response.json(); if (!response.ok) throw new Error(body.error || 'Could not load coupons'); setCoupons(body.coupons || []); setPage(body.page || nextPage); setPages(body.pages || 1); setTotal(body.total || 0) } catch (e) { setError(e.message) } finally { setLoading(false) } }
  useEffect(() => { load(1) }, [adminKey, status])
  const field = (key, value) => setForm((current) => ({ ...current, [key]: value }))
  const save = async (event) => { event.preventDefault(); setSaving(true); setError(''); try { const payload = { ...form, discountValue: Number(form.discountValue), minimumOrderAmount: Number(form.minimumOrderAmount || 0), maximumDiscount: form.maximumDiscount === '' ? null : Number(form.maximumDiscount), usageLimit: form.usageLimit === '' ? null : Number(form.usageLimit) }; const response = await fetch(`http://localhost:4000/api/admin/coupons${form.id ? `/${form.id}` : ''}`, { method: form.id ? 'PATCH' : 'POST', headers: { 'Content-Type': 'application/json', 'x-admin-key': adminKey }, body: JSON.stringify(payload) }); const body = await response.json(); if (!response.ok) throw new Error(body.error || 'Could not save coupon'); setForm(null); setToast(form.id ? 'Coupon updated.' : 'Coupon created.'); load(1) } catch (e) { setError(e.message) } finally { setSaving(false) } }
  const remove = async (coupon) => { if (!window.confirm(`Delete coupon ${coupon.code}?`)) return; const response = await fetch(`http://localhost:4000/api/admin/coupons/${coupon.id}`, { method: 'DELETE', headers: { 'x-admin-key': adminKey } }); if (!response.ok) { setError('Could not delete coupon'); return } setToast('Coupon deleted.'); load(page) }
  const toggle = async (coupon) => { const response = await fetch(`http://localhost:4000/api/admin/coupons/${coupon.id}`, { method: 'PATCH', headers: { 'Content-Type': 'application/json', 'x-admin-key': adminKey }, body: JSON.stringify({ enabled: !coupon.enabled }) }); if (!response.ok) { const body = await response.json().catch(() => ({})); setError(body.error || 'Could not update coupon'); return } setToast(coupon.enabled ? 'Coupon disabled.' : 'Coupon enabled.'); load(page) }
  useEffect(() => { if (!toast) return undefined; const timer = setTimeout(() => setToast(''), 3000); return () => clearTimeout(timer) }, [toast])
  return <div className="admin-content coupons-page"><div className="admin-toolbar coupon-toolbar"><div><p className="admin-eyebrow">Live MongoDB records</p><h2>Coupons <span className="notification-count">{total}</span></h2><p className="section-subtitle">Create and manage promotional offers for your customers.</p></div><button className="admin-primary" onClick={() => { setError(''); setForm({ ...emptyCoupon, startDate: new Date().toISOString().slice(0, 10) }) }}><Plus size={15} /> Create coupon</button></div>{toast && <div className="coupon-toast"><Check size={15} /> {toast}</div>}{error && <div className="settings-alert form-error">{error}</div>}<div className="coupon-filters"><input value={search} onChange={(e) => setSearch(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && load(1)} placeholder="Search coupon code..." /><button className="export-button" onClick={() => load(1)}><Search size={14} /> Search</button><select value={status} onChange={(e) => setStatus(e.target.value)}><option value="all">All statuses</option><option value="active">Active</option><option value="scheduled">Scheduled</option><option value="expired">Expired</option><option value="disabled">Disabled</option></select></div>{loading ? <AdminLoading /> : <div className="admin-card coupon-table-card"><div className="coupon-table-head"><span>Coupon</span><span>Discount</span><span>Validity</span><span>Usage</span><span>Status</span><span>Actions</span></div>{coupons.map((coupon) => <div className="coupon-row" key={coupon.id}><div><strong>{coupon.code}</strong><small>Min. order ${Number(coupon.minimumOrderAmount || 0).toFixed(2)}</small></div><span>{coupon.discountType === 'percentage' ? `${coupon.discountValue}%` : `$${Number(coupon.discountValue).toFixed(2)}`}{coupon.maximumDiscount !== null && coupon.maximumDiscount !== undefined ? <small>Max ${Number(coupon.maximumDiscount).toFixed(2)}</small> : null}</span><span>{new Date(coupon.startDate).toLocaleDateString()}<small>to {new Date(coupon.expiryDate).toLocaleDateString()}</small></span><span>{coupon.usedCount || 0}{coupon.usageLimit ? ` / ${coupon.usageLimit}` : ' / ∞'}</span><span className={`coupon-status ${coupon.status.toLowerCase()}`}>{coupon.status}</span><div className="coupon-actions"><button className="export-button" onClick={() => setForm({ ...coupon, startDate: new Date(coupon.startDate).toISOString().slice(0, 10), expiryDate: new Date(coupon.expiryDate).toISOString().slice(0, 10) })}>Edit</button><button className="export-button" onClick={() => toggle(coupon)}>{coupon.enabled ? 'Disable' : 'Enable'}</button><button className="notification-delete" onClick={() => remove(coupon)}><X size={15} /></button></div></div>)}{!coupons.length && <div className="coupon-empty"><Tag size={28} /><h3>No live coupons yet.</h3><p>Create your first coupon to see it here.</p></div>}<div className="pagination"><button disabled={page <= 1} onClick={() => load(page - 1)}>Previous</button><span>Page {page} of {pages}</span><button disabled={page >= pages} onClick={() => load(page + 1)}>Next</button></div></div>}{form && <CouponForm form={form} field={field} save={save} saving={saving} close={() => setForm(null)} />}</div>
}
function CouponForm({ form, field, save, saving, close }) { return <div className="modal-backdrop"><form className="admin-form-modal coupon-form" onSubmit={save}><button type="button" className="modal-close" onClick={close}><X size={19} /></button><p className="admin-eyebrow">{form.id ? 'Edit promotion' : 'New promotion'}</p><h2>{form.id ? 'Edit coupon' : 'Create coupon'}</h2><div className="coupon-form-grid"><label>Coupon code<input value={form.code} onChange={(e) => field('code', e.target.value.toUpperCase())} placeholder="SABLE10" required maxLength="32" /></label><label>Discount type<select value={form.discountType} onChange={(e) => field('discountType', e.target.value)}><option value="percentage">Percentage</option><option value="fixed">Fixed amount</option></select></label><label>Discount value<input type="number" min="0.01" step="0.01" value={form.discountValue} onChange={(e) => field('discountValue', e.target.value)} required /></label><label>Minimum order amount<input type="number" min="0" step="0.01" value={form.minimumOrderAmount} onChange={(e) => field('minimumOrderAmount', e.target.value)} /></label><label>Maximum discount<input type="number" min="0" step="0.01" value={form.maximumDiscount ?? ''} onChange={(e) => field('maximumDiscount', e.target.value)} /></label><label>Usage limit<input type="number" min="1" step="1" value={form.usageLimit ?? ''} onChange={(e) => field('usageLimit', e.target.value)} placeholder="Unlimited" /></label><label>Start date<input type="date" value={form.startDate} onChange={(e) => field('startDate', e.target.value)} required /></label><label>Expiry date<input type="date" value={form.expiryDate} onChange={(e) => field('expiryDate', e.target.value)} required /></label></div><label className="settings-toggle coupon-enabled"><span>Coupon enabled</span><input type="checkbox" checked={Boolean(form.enabled)} onChange={(e) => field('enabled', e.target.checked)} /><i /></label><div className="coupon-form-actions"><button type="button" className="export-button" onClick={close}>Cancel</button><button className="admin-primary" disabled={saving}>{saving ? 'Saving...' : form.id ? 'Save changes' : 'Create coupon'}</button></div></form></div> }
const emptySettings = { store: { storeName: '', logo: '', contactEmail: '', phone: '', address: '', currency: 'USD' }, shipping: { methods: [], charges: 0, freeShippingThreshold: 0 }, tax: { percentage: 0, enabled: false }, orders: { allowedStatuses: [], cancellationEnabled: true, returnsEnabled: true, refundPolicy: '' }, notifications: { emailNotifications: true, orderNotifications: true, lowStockAlerts: false }, social: { facebook: '', instagram: '', youtube: '', other: '' }, system: { maintenanceMode: false } }
function AdminSettings({ adminKey, setNotice }) {
  const [settings, setSettings] = useState(emptySettings); const [loading, setLoading] = useState(true); const [saving, setSaving] = useState(false); const [error, setError] = useState(''); const [savedAt, setSavedAt] = useState('')
  useEffect(() => { fetch('http://localhost:4000/api/admin/settings', { headers: { 'x-admin-key': adminKey } }).then(async (response) => { const body = await response.json(); if (!response.ok) throw new Error(body.error || 'Could not load settings'); if (body.settings) setSettings((current) => ({ ...current, ...body.settings })); }).catch((e) => setError(e.message)).finally(() => setLoading(false)) }, [adminKey])
  const update = (section, key, value) => setSettings((current) => ({ ...current, [section]: { ...current[section], [key]: value } }))
  const save = async (event) => { event.preventDefault(); setError(''); setSaving(true); try { if (!settings.store.storeName.trim()) throw new Error('Store name is required.'); if (settings.store.contactEmail && !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(settings.store.contactEmail)) throw new Error('Enter a valid contact email.'); const response = await fetch('http://localhost:4000/api/admin/settings', { method: 'PATCH', headers: { 'Content-Type': 'application/json', 'x-admin-key': adminKey }, body: JSON.stringify({ ...settings, shipping: { ...settings.shipping, methods: settings.shipping.methods.filter(Boolean) } }) }); const body = await response.json(); if (!response.ok) throw new Error(body.error || 'Could not save settings'); setSettings((current) => ({ ...current, ...body.settings })); setSavedAt(new Date().toLocaleTimeString()); setNotice('Settings saved to MongoDB'); } catch (e) { setError(e.message) } finally { setSaving(false) } }
  if (loading) return <div className="admin-content"><AdminLoading /></div>
  return <div className="admin-content settings-page"><div className="settings-intro"><div><p className="admin-eyebrow">Store configuration</p><h2>Settings</h2><p className="section-subtitle">Manage the live storefront configuration saved in MongoDB.</p></div>{savedAt && <span className="settings-saved"><Check size={14} /> Saved at {savedAt}</span>}</div>{error && <div className="settings-alert form-error">{error}</div>}<form onSubmit={save}><SettingsCard title="Store" description="The identity and contact details customers see."><div className="settings-grid"><SettingsInput label="Store name" value={settings.store.storeName} onChange={(v) => update('store', 'storeName', v)} required /><SettingsInput label="Logo URL" value={settings.store.logo} onChange={(v) => update('store', 'logo', v)} placeholder="https://..." /><SettingsInput label="Contact email" type="email" value={settings.store.contactEmail} onChange={(v) => update('store', 'contactEmail', v)} /><SettingsInput label="Phone" value={settings.store.phone} onChange={(v) => update('store', 'phone', v)} /><SettingsInput label="Address" value={settings.store.address} onChange={(v) => update('store', 'address', v)} /><SettingsInput label="Currency" value={settings.store.currency} onChange={(v) => update('store', 'currency', v)} placeholder="USD" /></div></SettingsCard><SettingsCard title="Shipping" description="Set available delivery methods and free-shipping rules."><div className="settings-grid"><SettingsInput label="Shipping methods" value={settings.shipping.methods.join(', ')} onChange={(v) => update('shipping', 'methods', v.split(',').map((item) => item.trim()).filter(Boolean))} placeholder="Standard, Express" /><SettingsInput label="Shipping charge" type="number" min="0" value={settings.shipping.charges} onChange={(v) => update('shipping', 'charges', Number(v))} /><SettingsInput label="Free shipping threshold" type="number" min="0" value={settings.shipping.freeShippingThreshold} onChange={(v) => update('shipping', 'freeShippingThreshold', Number(v))} /></div></SettingsCard><SettingsCard title="Tax" description="Control whether tax is applied at checkout."><div className="settings-grid"><SettingsInput label="Tax percentage" type="number" min="0" max="100" value={settings.tax.percentage} onChange={(v) => update('tax', 'percentage', Number(v))} /><SettingsToggle label="Enable tax" checked={settings.tax.enabled} onChange={(v) => update('tax', 'enabled', v)} /></div></SettingsCard><SettingsCard title="Orders" description="Define order lifecycle and customer aftercare."><div className="settings-grid"><SettingsInput label="Order statuses" value={settings.orders.allowedStatuses.join(', ')} onChange={(v) => update('orders', 'allowedStatuses', v.split(',').map((item) => item.trim()).filter(Boolean))} placeholder="Pending, Confirmed, Shipped, Delivered" /><SettingsToggle label="Allow cancellations" checked={settings.orders.cancellationEnabled} onChange={(v) => update('orders', 'cancellationEnabled', v)} /><SettingsToggle label="Allow returns and refunds" checked={settings.orders.returnsEnabled} onChange={(v) => update('orders', 'returnsEnabled', v)} /><SettingsInput label="Return / refund policy" value={settings.orders.refundPolicy} onChange={(v) => update('orders', 'refundPolicy', v)} /></div></SettingsCard><SettingsCard title="Notifications" description="Choose which operational alerts are enabled."><div className="settings-grid"><SettingsToggle label="Email notifications" checked={settings.notifications.emailNotifications} onChange={(v) => update('notifications', 'emailNotifications', v)} /><SettingsToggle label="Order notifications" checked={settings.notifications.orderNotifications} onChange={(v) => update('notifications', 'orderNotifications', v)} /><SettingsToggle label="Low-stock alerts" checked={settings.notifications.lowStockAlerts} onChange={(v) => update('notifications', 'lowStockAlerts', v)} /></div></SettingsCard><SettingsCard title="Social" description="Links used by the storefront footer and social gallery."><div className="settings-grid"><SettingsInput label="Facebook" value={settings.social.facebook} onChange={(v) => update('social', 'facebook', v)} /><SettingsInput label="Instagram" value={settings.social.instagram} onChange={(v) => update('social', 'instagram', v)} /><SettingsInput label="YouTube" value={settings.social.youtube} onChange={(v) => update('social', 'youtube', v)} /><SettingsInput label="Other social link" value={settings.social.other} onChange={(v) => update('social', 'other', v)} /></div></SettingsCard><SettingsCard title="System" description="Maintenance mode is stored server-side and should be enabled only during planned work."><SettingsToggle label="Maintenance mode" checked={settings.system.maintenanceMode} onChange={(v) => update('system', 'maintenanceMode', v)} /></SettingsCard><div className="settings-actions"><button className="admin-primary" disabled={saving}>{saving ? 'Saving to MongoDB...' : 'Save settings'} <Check size={15} /></button></div></form></div>
}
